class Solution {
public:
    vector<int> findBuildings(vector<int>& heights) {
        vector<int> answer;
        int tallest = -1;
        for (int i = static_cast<int>(heights.size()) - 1; i >= 0; --i) {
            if (heights[i] > tallest) {
                answer.push_back(i);
                tallest = heights[i];
            }
        }
        reverse(answer.begin(), answer.end());
        return answer;
    }
};
